import { IHttp, IModify, IPersistence, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { IJobContext } from '@rocket.chat/apps-engine/definition/scheduler';
import { App } from '@rocket.chat/apps-engine/definition/App';

import { ScheduledMessageStore } from '../lib/ScheduledMessageStore';
import { rearm } from './SendScheduledMessage';

export const REPAIR_PROCESSOR_ID = 'repair-recurring';

// a job that should already have fired this long ago has lost its chain
const STALE_AFTER_MS = 10 * 60 * 1000;

/**
 * Recurring messages work by arming one job at a time, so a chain broken
 * mid-flight (app disabled while a job fired, a scheduler error) would
 * leave a record that never runs again. This sweep re-arms those records.
 * It only schedules, never delivers, so an extra run cannot double-post.
 */
export function makeRepairRecurringProcessor(app: App) {
    return async (_jobContext: IJobContext, read: IRead, modify: IModify, _http: IHttp, persis: IPersistence): Promise<void> => {
        try {
            const all = await ScheduledMessageStore.listAll(read.getPersistenceReader());
            const cutoff = Date.now() - STALE_AFTER_MS;
            const stale = all.filter((r) => r.recurrence && new Date(r.whenIso).getTime() < cutoff);
            if (!stale.length) {
                return;
            }
            for (const record of stale) {
                const owner = await read.getUserReader().getById(record.userId);
                const repaired = await rearm(app, modify, persis, record, owner ? owner.utcOffset : record.utcOffset, new Date());
                app.getLogger().warn(`Repair sweep ${repaired ? 're-armed' : 'failed to re-arm'} recurring message ${record.shortId}`);
            }
        } catch (err) {
            app.getLogger().error('Recurring repair sweep failed:', err);
        }
    };
}

import { IPersistence, IPersistenceRead } from '@rocket.chat/apps-engine/definition/accessors';
import { RocketChatAssociationModel, RocketChatAssociationRecord } from '@rocket.chat/apps-engine/definition/metadata';

import { IRecurrence } from './TimeParser';

export interface IScheduledMessageRecord {
    shortId: string;
    jobId: string;
    userId: string;
    roomId: string;           // room the command was typed in (delivery target when no explicit targets)
    targetUsernames: Array<string>; // deliver as a DM to each
    targetChannelIds?: Array<string>; // deliver to each channel (optional: predates v0.0.14 records)
    kind?: 'delay' | 'remind'; // remind = bot DMs the scheduling user (optional: predates v0.0.32 records)
    recurrence?: IRecurrence; // present = repeats; whenIso is the NEXT occurrence (optional: predates v0.0.35)
    occurrenceCount?: number; // deliveries so far, recurring only (optional: predates v0.0.35)
    text: string;
    whenIso: string;
    createdAtIso: string;
    lang: string;
    utcOffset?: number;
}

const ALL = new RocketChatAssociationRecord(RocketChatAssociationModel.MISC, 'scheduled-message-record');

const byId = (shortId: string) =>
    new RocketChatAssociationRecord(RocketChatAssociationModel.MISC, `sched:${shortId}`);

const byUser = (userId: string) =>
    new RocketChatAssociationRecord(RocketChatAssociationModel.USER, userId);

export class ScheduledMessageStore {
    public static async save(persis: IPersistence, record: IScheduledMessageRecord): Promise<void> {
        await persis.createWithAssociations(record, [ALL, byId(record.shortId), byUser(record.userId)]);
    }

    public static async getById(persisRead: IPersistenceRead, shortId: string): Promise<IScheduledMessageRecord | undefined> {
        const results = await persisRead.readByAssociations([ALL, byId(shortId)]);
        return results.length ? results[0] as IScheduledMessageRecord : undefined;
    }

    public static async listByUser(persisRead: IPersistenceRead, userId: string): Promise<Array<IScheduledMessageRecord>> {
        const results = await persisRead.readByAssociations([ALL, byUser(userId)]);
        return (results as Array<IScheduledMessageRecord>)
            .slice()
            .sort((a, b) => a.whenIso.localeCompare(b.whenIso));
    }

    /** Every record in the workspace: used only by the recurring repair sweep. */
    public static async listAll(persisRead: IPersistenceRead): Promise<Array<IScheduledMessageRecord>> {
        const results = await persisRead.readByAssociations([ALL]);
        return results as Array<IScheduledMessageRecord>;
    }

    /**
     * The server matches update queries on the WHOLE associations array, not
     * a subset the way reads and removes do, so this must pass exactly the
     * three associations used at save time or the write silently does
     * nothing. upsert is false so a concurrently cancelled record cannot be
     * resurrected by a late re-arm.
     */
    public static async update(persis: IPersistence, record: IScheduledMessageRecord): Promise<void> {
        await persis.updateByAssociations([ALL, byId(record.shortId), byUser(record.userId)], record, false);
    }

    public static async removeById(persis: IPersistence, shortId: string): Promise<void> {
        await persis.removeByAssociations([ALL, byId(shortId)]);
    }
}

import { IModify, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { IRoom, RoomType } from '@rocket.chat/apps-engine/definition/rooms';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

/**
 * Returns the DM room between the two users, creating it if it does not
 * exist yet.
 */
export async function getOrCreateDirectRoom(read: IRead, modify: IModify, sender: IUser, targetUsername: string): Promise<IRoom> {
    const usernames = [sender.username, targetUsername];
    try {
        const existing = await read.getRoomReader().getDirectByUsernames(usernames);
        if (existing) {
            return existing;
        }
    } catch {
        // fall through and create
    }

    const builder = modify.getCreator().startRoom()
        .setType(RoomType.DIRECT_MESSAGE)
        .setCreator(sender)
        .setMembersToBeAddedByUsernames(usernames);
    const roomId = await modify.getCreator().finish(builder);
    const room = await read.getRoomReader().getById(roomId);
    if (!room) {
        throw new Error(`Could not create direct room with ${targetUsername}`);
    }
    return room;
}

export async function sendAsUser(modify: IModify, sender: IUser, room: IRoom, text: string): Promise<void> {
    const builder = modify.getCreator().startMessage()
        .setSender(sender)
        .setRoom(room)
        .setText(text);
    await modify.getCreator().finish(builder);
}

import { IHttp, IModify, IPersistence, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { App } from '@rocket.chat/apps-engine/definition/App';
import { IRoom } from '@rocket.chat/apps-engine/definition/rooms';
import { ISlashCommand, SlashCommandContext } from '@rocket.chat/apps-engine/definition/slashcommands';
import { ButtonStyle } from '@rocket.chat/apps-engine/definition/uikit';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

import { cancelAll, cancelOne, createSchedule, listMessages } from '../lib/Actions';
import { getUserLanguage, t } from '../lib/i18n';
import { notifyUser } from '../lib/Notifications';
import { formatDuration, formatRecurrence, formatWhen } from '../lib/TimeParser';

/**
 * Personal reminders: same parser and scheduler as /delay, but the target
 * is fixed to the scheduling user and delivery comes FROM the app bot in
 * the bot DM. Sending as the user into a self-DM would never notify them
 * (own messages do not ping), so the bot identity is deliberate here.
 */
export class RemindCommand implements ISlashCommand {
    public command = 'remind';
    public i18nParamsExample = 'remind_command_params';
    public i18nDescription = 'remind_command_description';
    public providesPreview = false;

    constructor(private readonly app: App) {}

    public async executor(context: SlashCommandContext, read: IRead, modify: IModify, _http: IHttp, persis: IPersistence): Promise<void> {
        const user = context.getSender();
        const room = context.getRoom();
        const lang = getUserLanguage(user);
        const args = context.getArguments().filter((a) => a && a.trim().length > 0);

        const notify = (text: string) => notifyUser(this.app, read, modify, user, room, text);

        const sub = (args[0] || 'help').toLowerCase();

        if (args.length === 0 || sub === 'help') {
            await notify(t(lang, 'remind_help_text'));
            return;
        }
        if (sub === 'list') {
            await listMessages(this.app, read, modify, user, room, lang, undefined, 'remind');
            return;
        }
        if (sub === 'cancel') {
            const target = (args[1] || '').toLowerCase();
            if (!target) {
                await notify(t(lang, 'cancel_usage', { cmd: 'remind' }));
                return;
            }
            if (target === 'all') {
                await cancelAll(this.app, read, modify, persis, user, lang, notify, 'remind');
                return;
            }
            await cancelOne(this.app, read, modify, persis, user, lang, target, notify);
            return;
        }

        await this.schedule(read, modify, persis, notify, user, room, lang, args);
    }

    private async schedule(
        read: IRead, modify: IModify, persis: IPersistence,
        notify: (text: string) => Promise<void>,
        user: IUser, room: IRoom, lang: string, args: Array<string>,
    ): Promise<void> {
        const raw = args.join(' ');
        const sayMatch = /(^|\s)say(\s|$)/i.exec(raw);
        if (!sayMatch) {
            await notify(t(lang, 'err_no_message', { cmd: 'remind' }));
            return;
        }
        const sayStart = sayMatch.index + sayMatch[1].length;
        const text = raw.slice(sayStart + 'say'.length).replace(/^\s+/, '');
        if (!text) {
            await notify(t(lang, 'err_say_no_text'));
            return;
        }
        const timeTokens = raw.slice(0, sayStart).split(/\s+/).filter(Boolean);

        const result = await createSchedule(this.app, read, modify, persis, user, room, lang, {
            timeTokens, text, targetUsernames: [], targetChannelIds: [], kind: 'remind',
        });
        if (!result.ok) {
            await notify(t(lang, result.errorKey, { cmd: 'remind', ...result.errorParams }));
            return;
        }

        const firstWhen = formatWhen(result.when, result.usedServerTz ? undefined : user.utcOffset, lang);
        let confirmation = result.recurrence
            ? t(lang, 'confirm_scheduled_recurring', {
                id: result.record.shortId,
                target: t(lang, 'confirm_target_reminder'),
                recurrence: formatRecurrence(result.recurrence, lang),
                next: firstWhen,
            })
            : t(lang, 'confirm_scheduled', {
                id: result.record.shortId,
                target: t(lang, 'confirm_target_reminder'),
                when: firstWhen,
                relative: t(lang, 'relative_in', { duration: formatDuration(result.delayMs) }),
            });
        if (result.usedServerTz) {
            confirmation += `\n${t(lang, 'tz_warning')}`;
        }

        const blocks = modify.getCreator().getBlockBuilder();
        blocks.addSectionBlock({ text: blocks.newMarkdownTextObject(confirmation) });
        blocks.addActionsBlock({
            elements: [
                blocks.newButtonElement({
                    actionId: 'delay-cancel',
                    text: blocks.newPlainTextObject(t(lang, 'btn_cancel')),
                    value: result.record.shortId,
                    style: ButtonStyle.DANGER,
                }),
                blocks.newButtonElement({
                    actionId: 'delay-list',
                    text: blocks.newPlainTextObject(t(lang, 'btn_list')),
                }),
            ],
        });
        await notifyUser(this.app, read, modify, user, room, confirmation, blocks);
    }
}

import { IModify, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { App } from '@rocket.chat/apps-engine/definition/App';
import { IRoom } from '@rocket.chat/apps-engine/definition/rooms';
import { BlockBuilder } from '@rocket.chat/apps-engine/definition/uikit';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

/**
 * Sends an ephemeral notification, visible only to the given user,
 * sent by the app user (official-app convention).
 */
export async function notifyUser(app: App, read: IRead, modify: IModify, user: IUser, room: IRoom, text: string, blocks?: BlockBuilder): Promise<void> {
    const appUser = await read.getUserReader().getAppUser(app.getID());
    const message = modify.getCreator().startMessage()
        .setSender(appUser || user)
        .setRoom(room)
        .setText(text)
        .setGroupable(false)
        // the app user's stored avatar snapshots at install time, so point
        // at the live app icon instead of relying on it
        .setAvatarUrl(`/api/apps/${app.getID()}/icon`);
    if (blocks) {
        message.setBlocks(blocks);
    }
    await read.getNotifier().notifyUser(user, message.getMessage());
}

import { IHttp, IModify, IPersistence, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { IJobContext } from '@rocket.chat/apps-engine/definition/scheduler';
import { App } from '@rocket.chat/apps-engine/definition/App';

import { RoomType } from '@rocket.chat/apps-engine/definition/rooms';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

import { canPostTo } from '../lib/Actions';
import { t } from '../lib/i18n';
import { getOrCreateDirectRoom, sendAsUser } from '../lib/MessageDelivery';
import { IScheduledMessageRecord, ScheduledMessageStore } from '../lib/ScheduledMessageStore';
import { nextOccurrence } from '../lib/TimeParser';

export const SEND_MESSAGE_PROCESSOR_ID = 'scheduled-message';

interface IDeliveryOutcome {
    /** a target is gone or the sender lost access to it */
    unreachable?: string;
}

async function deliver(
    app: App, read: IRead, modify: IModify,
    record: IScheduledMessageRecord, sender: IUser,
): Promise<IDeliveryOutcome> {
    // reminders are delivered BY the app bot into the bot DM: a
    // message sent as the user to themselves would never notify them
    if (record.kind === 'remind') {
        const appUser = await read.getUserReader().getAppUser(app.getID());
        if (!appUser) {
            throw new Error('App user not found for reminder delivery');
        }
        const dm = await getOrCreateDirectRoom(read, modify, appUser, sender.username);
        await sendAsUser(modify, appUser, dm, t(record.lang, 'remind_delivery', { text: record.text }));
        return {};
    }

    const channelIds = record.targetChannelIds || [];
    const usernames = record.targetUsernames || [];

    // membership was validated at schedule time, but time passes before the
    // job fires: re-check at delivery so a user who left or was removed
    // cannot still post into the room
    if (channelIds.length || usernames.length) {
        let unreachable: string | undefined;
        for (const channelId of channelIds) {
            const channel = await read.getRoomReader().getById(channelId);
            if (!channel) {
                app.getLogger().warn(`Channel ${channelId} for scheduled message ${record.shortId} no longer exists, skipping`);
                unreachable = channelId;
                continue;
            }
            if (!(await canPostTo(read, channel, sender.id))) {
                app.getLogger().warn(`Sender can no longer post in ${channel.slugifiedName}, skipping ${record.shortId} for that channel`);
                unreachable = `#${channel.displayName || channel.slugifiedName}`;
                continue;
            }
            await sendAsUser(modify, sender, channel, record.text);
        }
        for (const username of usernames) {
            const room = await getOrCreateDirectRoom(read, modify, sender, username);
            await sendAsUser(modify, sender, room, record.text);
        }
        return { unreachable };
    }

    const room = await read.getRoomReader().getById(record.roomId);
    if (!room) {
        throw new Error(`Room ${record.roomId} no longer exists`);
    }
    if (!(await canPostTo(read, room, sender.id))) {
        app.getLogger().warn(`Sender can no longer post in ${room.slugifiedName}, dropping ${record.shortId}`);
        return { unreachable: `#${room.displayName || room.slugifiedName}` };
    }
    await sendAsUser(modify, sender, room, record.text);
    return {};
}

/**
 * Arms the next occurrence of a recurring record in place. The offset is
 * read from the live user rather than the record so a series follows the
 * user's timezone after a DST change.
 */
export async function rearm(
    app: App, modify: IModify, persis: IPersistence,
    record: IScheduledMessageRecord, utcOffset: number | undefined, after: Date,
): Promise<boolean> {
    if (!record.recurrence) {
        return false;
    }
    const when = nextOccurrence(record.recurrence, after, utcOffset);
    let jobId: string | void = undefined;
    try {
        jobId = await modify.getScheduler().scheduleOnce({
            id: SEND_MESSAGE_PROCESSOR_ID,
            when,
            data: { shortId: record.shortId },
        });
    } catch (err) {
        app.getLogger().error(`Failed to re-arm recurring message ${record.shortId}:`, err);
    }
    if (!jobId) {
        // leave the record alone: the repair sweep re-arms it later
        return false;
    }
    record.jobId = jobId;
    record.whenIso = when.toISOString();
    record.utcOffset = utcOffset;
    await ScheduledMessageStore.update(persis, record);
    return true;
}

export function makeSendScheduledMessageProcessor(app: App) {
    return async (jobContext: IJobContext, read: IRead, modify: IModify, _http: IHttp, persis: IPersistence): Promise<void> => {
        const { shortId } = jobContext as { shortId?: string };
        if (!shortId) {
            app.getLogger().error('Scheduled job fired without a shortId in its context');
            return;
        }

        // the persistence record is the source of truth: if it is gone,
        // the message was cancelled and this job must not deliver
        const record = await ScheduledMessageStore.getById(read.getPersistenceReader(), shortId);
        if (!record) {
            app.getLogger().debug(`Scheduled message ${shortId} has no record, treating as cancelled`);
            return;
        }

        let sender: IUser | undefined;
        let outcome: IDeliveryOutcome = {};
        try {
            sender = await read.getUserReader().getById(record.userId);
            if (!sender) {
                throw new Error(`Sender ${record.userId} no longer exists`);
            }
            outcome = await deliver(app, read, modify, record, sender);
        } catch (err) {
            app.getLogger().error(`Failed to deliver scheduled message ${shortId}:`, err);
        }

        // one-shot messages are spent once they fire, however they went
        if (!record.recurrence) {
            await ScheduledMessageStore.removeById(persis, shortId);
            return;
        }

        // losing access to a target ends the series, and the owner is told
        if (outcome.unreachable) {
            await ScheduledMessageStore.removeById(persis, shortId);
            try {
                const appUser = await read.getUserReader().getAppUser(app.getID());
                if (appUser && sender) {
                    const dm = await getOrCreateDirectRoom(read, modify, appUser, sender.username);
                    await sendAsUser(modify, appUser, dm, t(record.lang, 'recur_cancelled_access', {
                        id: record.shortId,
                        target: outcome.unreachable,
                    }));
                }
            } catch (err) {
                app.getLogger().error(`Could not notify owner about cancelled series ${shortId}:`, err);
            }
            return;
        }

        record.occurrenceCount = (record.occurrenceCount || 0) + 1;
        // never re-arm behind the occurrence just handled, so the series
        // always moves forward even if the job ran a moment early
        const after = new Date(Math.max(Date.now(), new Date(record.whenIso).getTime()));
        await rearm(app, modify, persis, record, sender ? sender.utcOffset : record.utcOffset, after);
    };
}

import { IHttp, IModify, IPersistence, IRead } from '@rocket.chat/apps-engine/definition/accessors';
import { App } from '@rocket.chat/apps-engine/definition/App';
import { IRoom, RoomType } from '@rocket.chat/apps-engine/definition/rooms';
import { ISlashCommand, SlashCommandContext } from '@rocket.chat/apps-engine/definition/slashcommands';
import { ButtonStyle } from '@rocket.chat/apps-engine/definition/uikit';
import { IUser } from '@rocket.chat/apps-engine/definition/users';

import { cancelAll, cancelOne, canPostTo, createSchedule, getSiteUrl, linkChannel, linkUsers, listMessages } from '../lib/Actions';
import { getUserLanguage, t } from '../lib/i18n';
import { notifyUser } from '../lib/Notifications';
import { formatDuration, formatRecurrence, formatWhen } from '../lib/TimeParser';

export class DelayCommand implements ISlashCommand {
    public command = 'delay';
    public i18nParamsExample = 'delay_command_params';
    public i18nDescription = 'delay_command_description';
    public providesPreview = false;

    constructor(private readonly app: App) {}

    public async executor(context: SlashCommandContext, read: IRead, modify: IModify, _http: IHttp, persis: IPersistence): Promise<void> {
        const user = context.getSender();
        const room = context.getRoom();
        const lang = getUserLanguage(user);
        const args = context.getArguments().filter((a) => a && a.trim().length > 0);

        const notify = (text: string) => notifyUser(this.app, read, modify, user, room, text);

        const sub = (args[0] || 'help').toLowerCase();

        if (args.length === 0 || sub === 'help') {
            await notify(t(lang, 'help_text'));
            return;
        }
        if (sub === 'list') {
            await listMessages(this.app, read, modify, user, room, lang);
            return;
        }
        if (sub === 'cancel') {
            await this.cancel(read, modify, persis, notify, user, lang, args.slice(1));
            return;
        }

        await this.schedule(read, modify, persis, notify, user, room, lang, args);
    }

    private async schedule(
        read: IRead, modify: IModify, persis: IPersistence,
        notify: (text: string) => Promise<void>,
        user: IUser, room: IRoom, lang: string, args: Array<string>,
    ): Promise<void> {
        // split on the "say" keyword against the reconstructed raw string,
        // not exact tokens: tokens can contain embedded newlines (quoted
        // strings, older servers), e.g. "say\nhello" must still match
        const raw = args.join(' ');
        const sayMatch = /(^|\s)say(\s|$)/i.exec(raw);
        if (!sayMatch) {
            await notify(t(lang, 'err_no_message', { cmd: 'delay' }));
            return;
        }
        const sayStart = sayMatch.index + sayMatch[1].length;
        const text = raw.slice(sayStart + 'say'.length).replace(/^\s+/, '');
        if (!text) {
            await notify(t(lang, 'err_say_no_text'));
            return;
        }

        // spec tokens (any order): @mentions + #channels + time expression
        const targetUsernames: Array<string> = [];
        const targetChannelNames: Array<string> = [];
        const timeTokens: Array<string> = [];
        for (const token of raw.slice(0, sayStart).split(/\s+/).filter(Boolean)) {
            if (token.startsWith('@') && token.length > 1) {
                targetUsernames.push(token.substring(1).replace(/[,]+$/, ''));
            } else if (token.startsWith('#') && token.length > 1) {
                targetChannelNames.push(token.substring(1).replace(/[,]+$/, ''));
            } else {
                timeTokens.push(token);
            }
        }

        // validate mentioned users exist before scheduling anything
        for (const username of targetUsernames) {
            const target = await read.getUserReader().getByUsername(username);
            if (!target) {
                await notify(t(lang, 'err_user_not_found', { username }));
                return;
            }
        }

        // validate channels exist and the user is a member: the message is
        // delivered as the user, so they must not reach rooms they cannot access
        const targetChannelIds: Array<string> = [];
        const resolvedChannels: Array<IRoom> = [];
        for (const name of targetChannelNames) {
            const channel = await read.getRoomReader().getByName(name);
            if (!channel || channel.type === RoomType.DIRECT_MESSAGE) {
                await notify(t(lang, 'err_channel_not_found', { name }));
                return;
            }
            if (!(await canPostTo(read, channel, user.id))) {
                await notify(t(lang, 'err_not_channel_member', { name }));
                return;
            }
            targetChannelIds.push(channel.id);
            resolvedChannels.push(channel);
        }

        const result = await createSchedule(this.app, read, modify, persis, user, room, lang, {
            timeTokens, text, targetUsernames, targetChannelIds, kind: 'delay',
        });
        if (!result.ok) {
            await notify(t(lang, result.errorKey, { cmd: 'delay', ...result.errorParams }));
            return;
        }
        const { record, when, delayMs, usedServerTz } = result;
        const shortId = record.shortId;
        const siteUrl = await getSiteUrl(this.app, read);

        const targetParts: Array<string> = [];
        if (resolvedChannels.length) {
            targetParts.push(t(lang, 'confirm_target_channels', {
                channels: resolvedChannels.map((c) => linkChannel(siteUrl, c)).join(', '),
            }));
        }
        if (targetUsernames.length) {
            targetParts.push(t(lang, 'confirm_target_dm', { users: linkUsers(siteUrl, targetUsernames) }));
        }
        const target = targetParts.length ? targetParts.join(' + ') : t(lang, 'confirm_target_room');
        const firstWhen = formatWhen(when, usedServerTz ? undefined : user.utcOffset, lang);
        let confirmation = result.recurrence
            ? t(lang, 'confirm_scheduled_recurring', {
                id: shortId,
                target,
                recurrence: formatRecurrence(result.recurrence, lang),
                next: firstWhen,
            })
            : t(lang, 'confirm_scheduled', {
                id: shortId,
                target,
                when: firstWhen,
                relative: t(lang, 'relative_in', { duration: formatDuration(delayMs) }),
            });
        if (usedServerTz) {
            confirmation += `\n${t(lang, 'tz_warning')}`;
        }

        // action buttons under the confirmation: cancel THIS message without
        // retyping the id, plus discoverable entry points for list and help
        const blocks = modify.getCreator().getBlockBuilder();
        blocks.addSectionBlock({ text: blocks.newMarkdownTextObject(confirmation) });
        blocks.addActionsBlock({
            elements: [
                blocks.newButtonElement({
                    actionId: 'delay-cancel',
                    text: blocks.newPlainTextObject(t(lang, 'btn_cancel')),
                    value: shortId,
                    style: ButtonStyle.DANGER,
                }),
                blocks.newButtonElement({
                    actionId: 'delay-list',
                    text: blocks.newPlainTextObject(t(lang, 'btn_list')),
                }),
                blocks.newButtonElement({
                    actionId: 'delay-help',
                    text: blocks.newPlainTextObject(t(lang, 'btn_help')),
                }),
            ],
        });
        await notifyUser(this.app, read, modify, user, room, confirmation, blocks);
    }

    private async cancel(
        read: IRead, modify: IModify, persis: IPersistence,
        notify: (text: string) => Promise<void>,
        user: IUser, lang: string, args: Array<string>,
    ): Promise<void> {
        const target = (args[0] || '').toLowerCase();
        if (!target) {
            await notify(t(lang, 'cancel_usage', { cmd: 'delay' }));
            return;
        }
        if (target === 'all') {
            await cancelAll(this.app, read, modify, persis, user, lang, notify);
            return;
        }
        await cancelOne(this.app, read, modify, persis, user, lang, target, notify);
    }
}

import { monthName, t, weekdayName } from './i18n';

export type ParseErrorKey =
    | 'err_seconds_unsupported'
    | 'err_no_time'
    | 'err_unknown_token'
    | 'err_mixed_time'
    | 'err_need_time_of_day'
    | 'err_past'
    | 'err_recur_unsupported';

/** A repeating schedule, always anchored to a wall-clock time of day. */
export interface IRecurrence {
    kind: 'daily' | 'weekdays' | 'weekly';
    weekday?: number; // 0 = Sunday, only for kind 'weekly'
    hours: number;
    minutes: number;
}

export interface IParseSuccess {
    ok: true;
    when: Date; // absolute UTC instant of the FIRST occurrence
    usedServerTz: boolean;
    recurrence?: IRecurrence;
}

export interface IParseFailure {
    ok: false;
    error: ParseErrorKey;
    token?: string;
}

export type ParseResult = IParseSuccess | IParseFailure;

const DURATION_RE = /^(?:\d+[mhdw])+$/i;
const DURATION_PART_RE = /(\d+)([mhdw])/gi;
// same shape but with a seconds part: matched only to give a clear error
const SECONDS_DURATION_RE = /^(?:\d+[smhdw])+$/i;
const CLOCK_RE = /^(\d{1,2})(?::(\d{2}))?(am|pm)?$/i;

const UNIT_MS: Record<string, number> = {
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
};

const WEEKDAYS: Record<string, number> = {
    sunday: 0, sun: 0,
    monday: 1, mon: 1,
    tuesday: 2, tue: 2, tues: 2,
    wednesday: 3, wed: 3,
    thursday: 4, thu: 4, thur: 4, thurs: 4,
    friday: 5, fri: 5,
    saturday: 6, sat: 6,
};

/**
 * Parses the time portion of a /delay invocation.
 *
 * Accepts a relative delay ("5m", "8h30m", "1h 30m"), a clock expression
 * ("8am tomorrow", "next monday 14:30", "noon today"), or a recurrence
 * ("every day at 8am", "every weekday at 9am", "every monday at 8am") in
 * any token order. Clock expressions resolve in the user's timezone via
 * utcOffsetHours; when that is undefined the server timezone is used and
 * usedServerTz is set so the caller can warn.
 */
export function parseTimeSpec(tokens: Array<string>, utcOffsetHours: number | undefined, now: Date): ParseResult {
    let durationMs = 0;
    let hasDuration = false;
    let clock: { hours: number, minutes: number } | undefined;
    let dayOffset: number | undefined;
    let weekday: number | undefined;
    let expectWeekday = false;
    let isRecurring = false;
    let recurDay: 'day' | 'weekday' | undefined;

    for (const raw of tokens) {
        const token = [REDACTED];

        if (expectWeekday) {
            if (WEEKDAYS[token] === undefined) {
                return { ok: false, error: 'err_unknown_token', token: raw };
            }
            weekday = WEEKDAYS[token];
            expectWeekday = false;
            continue;
        }

        if (DURATION_RE.test(token)) {
            hasDuration = true;
            let match = DURATION_PART_RE.exec(token);
            while (match) {
                durationMs += parseInt(match[1], 10) * UNIT_MS[match[2].toLowerCase()];
                match = DURATION_PART_RE.exec(token);
            }
            continue;
        }

        // reached only when the duration contains a seconds part, since the
        // seconds-free pattern is tried first
        if (SECONDS_DURATION_RE.test(token)) {
            return { ok: false, error: 'err_seconds_unsupported' };
        }

        if (token === 'noon') {
            clock = { hours: 12, minutes: 0 };
            continue;
        }
        if (token === 'midnight') {
            clock = { hours: 0, minutes: 0 };
            continue;
        }
        if (token === 'today') {
            dayOffset = 0;
            continue;
        }
        if (token === 'tomorrow') {
            dayOffset = 1;
            continue;
        }
        if (token === 'next') {
            expectWeekday = true;
            continue;
        }
        if (token === 'every') {
            isRecurring = true;
            continue;
        }
        // "day" and "weekday" only mean anything as recurrence periods
        if (isRecurring && (token === 'day' || token === 'daily')) {
            recurDay = 'day';
            continue;
        }
        if (isRecurring && (token === 'weekday' || token === 'weekdays')) {
            recurDay = 'weekday';
            continue;
        }
        if (WEEKDAYS[token] !== undefined) {
            weekday = WEEKDAYS[token];
            continue;
        }
        if (token === 'at' || token === 'on' || token === 'in') {
            continue; // connective noise words
        }

        const clockMatch = CLOCK_RE.exec(token);
        // require am/pm or an explicit colon so bare numbers stay errors
        if (clockMatch && (clockMatch[2] !== undefined || clockMatch[3] !== undefined)) {
            let hours = parseInt(clockMatch[1], 10);
            const minutes = clockMatch[2] ? parseInt(clockMatch[2], 10) : 0;
            const meridiem = clockMatch[3] ? clockMatch[3].toLowerCase() : undefined;
            if (hours > 23 || minutes > 59 || (meridiem && hours > 12)) {
                return { ok: false, error: 'err_unknown_token', token: raw };
            }
            if (meridiem === 'pm' && hours < 12) {
                hours += 12;
            }
            if (meridiem === 'am' && hours === 12) {
                hours = 0;
            }
            clock = { hours, minutes };
            continue;
        }

        return { ok: false, error: 'err_unknown_token', token: raw };
    }

    if (expectWeekday) {
        return { ok: false, error: 'err_need_time_of_day' };
    }

    if (isRecurring) {
        // only wall-clock patterns repeat: "every 2h" and "every tomorrow"
        // are not supported, and a period without a time cannot be resolved
        if (hasDuration || dayOffset !== undefined) {
            return { ok: false, error: 'err_recur_unsupported' };
        }
        if (recurDay === undefined && weekday === undefined) {
            return { ok: false, error: 'err_recur_unsupported' };
        }
        if (clock === undefined) {
            return { ok: false, error: 'err_need_time_of_day' };
        }
        let recurrence: IRecurrence;
        if (recurDay === 'day') {
            recurrence = { kind: 'daily', hours: clock.hours, minutes: clock.minutes };
        } else if (recurDay === 'weekday') {
            recurrence = { kind: 'weekdays', hours: clock.hours, minutes: clock.minutes };
        } else {
            recurrence = { kind: 'weekly', weekday, hours: clock.hours, minutes: clock.minutes };
        }
        return {
            ok: true,
            // the first occurrence is the next one strictly after now, so a
            // time still to come today fires today rather than next cycle
            when: nextOccurrence(recurrence, now, utcOffsetHours),
            usedServerTz: utcOffsetHours === undefined,
            recurrence,
        };
    }

    const hasClockExpr = clock !== undefined || dayOffset !== undefined || weekday !== undefined;

    if (hasDuration && hasClockExpr) {
        return { ok: false, error: 'err_mixed_time' };
    }

    if (hasDuration) {
        if (durationMs <= 0) {
            return { ok: false, error: 'err_no_time' };
        }
        return { ok: true, when: new Date(now.getTime() + durationMs), usedServerTz: false };
    }

    if (!hasClockExpr) {
        return { ok: false, error: 'err_no_time' };
    }

    if (clock === undefined) {
        // "tomorrow" / "next monday" alone: refuse to guess a time of day
        return { ok: false, error: 'err_need_time_of_day' };
    }

    const usedServerTz = utcOffsetHours === undefined;
    const cal = makeCalendar(utcOffsetHours);
    const nowParts = cal.parts(now);

    let daysAhead: number;
    if (weekday !== undefined) {
        daysAhead = (weekday - nowParts.dow + 7) % 7;
        if (daysAhead === 0) {
            daysAhead = 7; // "monday"/"next monday" on a Monday means next week
        }
    } else if (dayOffset !== undefined) {
        daysAhead = dayOffset;
    } else {
        daysAhead = 0; // bare time: today, rolling to tomorrow if past
    }

    let when = cal.build(nowParts.year, nowParts.month, nowParts.day + daysAhead, clock.hours, clock.minutes);

    if (when.getTime() <= now.getTime()) {
        if (weekday === undefined && dayOffset === undefined) {
            when = cal.build(nowParts.year, nowParts.month, nowParts.day + 1, clock.hours, clock.minutes);
        } else {
            return { ok: false, error: 'err_past' };
        }
    }

    return { ok: true, when, usedServerTz };
}

interface ICalendarParts {
    year: number;
    month: number;
    day: number;
    dow: number;
}

/**
 * Wall-clock arithmetic in the user's timezone (fixed offset in hours,
 * fractional offsets like 5.5 supported) or, when offset is undefined,
 * in the server's local timezone.
 */
function makeCalendar(utcOffsetHours: number | undefined) {
    if (utcOffsetHours === undefined) {
        return {
            parts: (d: Date): ICalendarParts => ({
                year: d.getFullYear(), month: d.getMonth(), day: d.getDate(), dow: d.getDay(),
            }),
            build: (year: number, month: number, day: number, hours: number, minutes: number): Date =>
                new Date(year, month, day, hours, minutes, 0, 0),
        };
    }
    const offsetMs = Math.round(utcOffsetHours * 60) * 60 * 1000;
    return {
        parts: (d: Date): ICalendarParts => {
            const wall = new Date(d.getTime() + offsetMs);
            return {
                year: wall.getUTCFullYear(), month: wall.getUTCMonth(), day: wall.getUTCDate(), dow: wall.getUTCDay(),
            };
        },
        build: (year: number, month: number, day: number, hours: number, minutes: number): Date =>
            new Date(Date.UTC(year, month, day, hours, minutes, 0, 0) - offsetMs),
    };
}

/**
 * The earliest occurrence of a recurrence strictly after `after`, resolved
 * in the given timezone. Scanning day by day keeps month and year rollover,
 * and the weekday arithmetic, in the hands of the calendar helper.
 */
export function nextOccurrence(recurrence: IRecurrence, after: Date, utcOffsetHours: number | undefined): Date {
    const cal = makeCalendar(utcOffsetHours);
    const parts = cal.parts(after);
    for (let i = 0; i <= 14; i++) {
        const candidate = cal.build(parts.year, parts.month, parts.day + i, recurrence.hours, recurrence.minutes);
        if (candidate.getTime() <= after.getTime()) {
            continue;
        }
        const dow = cal.parts(candidate).dow;
        if (recurrence.kind === 'daily'
            || (recurrence.kind === 'weekdays' && dow >= 1 && dow <= 5)
            || (recurrence.kind === 'weekly' && dow === recurrence.weekday)) {
            return candidate;
        }
    }
    // unreachable: weekly resolves within 7 days and weekdays within 3
    return cal.build(parts.year, parts.month, parts.day + 7, recurrence.hours, recurrence.minutes);
}

function pad2(value: number): string {
    return value < 10 ? `0${value}` : `${value}`;
}

/** Describes a recurrence, e.g. "every Monday at 08:00". */
export function formatRecurrence(recurrence: IRecurrence, lang: string): string {
    const time = `${pad2(recurrence.hours)}:${pad2(recurrence.minutes)}`;
    if (recurrence.kind === 'daily') {
        return t(lang, 'recur_daily', { time });
    }
    if (recurrence.kind === 'weekdays') {
        return t(lang, 'recur_weekdays', { time });
    }
    return t(lang, 'recur_weekly', { weekday: weekdayName(lang, recurrence.weekday || 0), time });
}

/** Formats an instant as the user's wall-clock time, e.g. "Monday 13 Jul 2026, 08:00". */
export function formatWhen(when: Date, utcOffsetHours: number | undefined, lang: string): string {
    const shifted = utcOffsetHours === undefined
        ? when
        : new Date(when.getTime() + Math.round(utcOffsetHours * 60) * 60 * 1000);

    const dow = utcOffsetHours === undefined ? shifted.getDay() : shifted.getUTCDay();
    const day = utcOffsetHours === undefined ? shifted.getDate() : shifted.getUTCDate();
    const month = utcOffsetHours === undefined ? shifted.getMonth() : shifted.getUTCMonth();
    const year = utcOffsetHours === undefined ? shifted.getFullYear() : shifted.getUTCFullYear();
    const hours = utcOffsetHours === undefined ? shifted.getHours() : shifted.getUTCHours();
    const minutes = utcOffsetHours === undefined ? shifted.getMinutes() : shifted.getUTCMinutes();

    const hh = hours < 10 ? `0${hours}` : `${hours}`;
    const mm = minutes < 10 ? `0${minutes}` : `${minutes}`;
    return `${weekdayName(lang, dow)} ${day} ${monthName(lang, month)} ${year}, ${hh}:${mm}`;
}

/** Formats a duration compactly, e.g. "2d 4h", "1h 30m", "45s". */
export function formatDuration(ms: number): string {
    const totalSeconds = Math.max(1, Math.round(ms / 1000));
    const days = Math.floor(totalSeconds / 86400);
    const hours = Math.floor((totalSeconds % 86400) / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const parts: Array<string> = [];
    if (days) {
        parts.push(`${days}d`);
    }
    if (hours) {
        parts.push(`${hours}h`);
    }
    if (minutes && !days) {
        parts.push(`${minutes}m`);
    }
    if (seconds && !days && !hours) {
        parts.push(`${seconds}s`);
    }
    return parts.join(' ') || '0s';
}
